/* W10_R01_SEARCH_V1 */
const c=$json.candidate||null;if(!c)return [];
const query=`${c.subject} facts explanation official source background science history geography how works`;return [{json:{candidate:c,searchBody:{query,search_depth:'basic',max_results:10,include_answer:false,include_raw_content:false,topic:'general'}}}];

/* W10_R01_PROMPT_V1 */
const base=$('Prepare evidence search').item.json;const c=base.candidate;const rows=($json?.results||[]).filter(r=>r?.url&&r?.content).slice(0,10).map((r,i)=>({source_id:i+1,url:String(r.url),title:String(r.title||''),content:String(r.content||'').replace(/\s+/g,' ').trim().slice(0,2200)}));
if(rows.length<3)throw new Error('Fewer than three usable evidence sources returned');
const system=`You research evidence-backed What10Things explainers. Return STRICT JSON only. Use ONLY supplied evidence. Never use unstated memory, never invent a source, and never convert a current event into live-news reporting. Output: {title,summary,intro,reading_time,items:[EXACTLY 10],related_topics:[0..6]}. Each item: {title,body,confidence,source_ids:[1..10]}. related_topics: {slug,title,subject,category,relationship,score,evergreen_score,rationale}. Each fact must be a distinct, durable claim directly supported by at least one chosen source. body 60-220 words, plain UK English. confidence 0.70..0.95; lower it when evidence is indirect. Prefer primary/official/academic sources where present. Do not claim hands-on testing or original reporting. Related topics must be evergreen and genuinely useful, not arbitrary expansion.`;
const user=JSON.stringify({candidate:{title:c.title,subject:c.subject,category:c.category,rationale:c.rationale},evidence:rows});
return [{json:{candidate:c,evidence:rows,system,user}}];

/* W10_R01_VALIDATE_V1 */
const base=$('Build evidence-grounded research prompt').item.json;const c=base.candidate;const evidence=base.evidence||[];const byId=new Map(evidence.map(x=>[Number(x.source_id),x]));
const raw=String($json?.choices?.[0]?.message?.content||'').replace(/```json|```/gi,'').trim();let x=null;try{x=JSON.parse(raw);}catch{}
const slugify=v=>String(v||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,120);const host=u=>{try{return new URL(u).hostname.replace(/^www\./,'')}catch{return ''}};
const allowed=new Set(['science-nature','world','history-culture','general-knowledge','technology','travel','home-living','money','everyday','buying-guides']);
let error='';let topic=null;
if(!x||!Array.isArray(x.items)){error='Free model did not return valid topic JSON';}
else{const items=[];for(const f of x.items){if(items.length>=10)break;const title=String(f?.title||'').trim(),body=String(f?.body||'').replace(/\s+/g,' ').trim();const ids=[...new Set((Array.isArray(f?.source_ids)?f.source_ids:[]).map(Number).filter(n=>byId.has(n)))];if(title.length<5||body.length<40||!ids.length)continue;const conf=Math.max(.70,Math.min(.95,Number(f.confidence)||.72));const sources=ids.slice(0,3).map(id=>{const s=byId.get(id);const domain=host(s.url);return {url:s.url,title:s.title,publisher:domain,source_type:/\.gov\.uk$|\.gov$|nhs\.uk$|\.edu$|\.ac\.uk$/i.test(domain)?'official':'independent',evidence_excerpt:String(s.content||'').slice(0,650)};});items.push({title,body,confidence:conf,sources});}
 if(items.length!==10){error=`Research produced ${items.length} valid sourced facts instead of 10`;}
 else{const rel=[];for(const r of (Array.isArray(x.related_topics)?x.related_topics:[]).slice(0,6)){const slug=slugify(r?.slug||r?.subject||r?.title);const cat=allowed.has(String(r?.category))?String(r.category):String(c.category||'general-knowledge');const score=Math.max(0,Math.min(1,Number(r?.score)||.65)),ever=Math.max(0,Math.min(1,Number(r?.evergreen_score)||score));if(slug&&slug!==c.slug&&score>=.65&&ever>=.70)rel.push({slug,title:String(r?.title||slug.replace(/-/g,' ')).slice(0,300),subject:String(r?.subject||r?.title||slug.replace(/-/g,' ')).slice(0,300),category:cat,relationship:String(r?.relationship||'related').slice(0,80),score,evergreen_score:ever,rationale:String(r?.rationale||'Related evidence-backed follow-up subject.').slice(0,1200)});} const domains=new Set(items.flatMap(i=>i.sources.map(s=>host(s.url))).filter(Boolean));const quality=Math.min(.94,.78+Math.min(.12,domains.size*.02));topic={slug:c.slug,title:String(x.title||c.title).slice(0,300),category:allowed.has(String(c.category))?String(c.category):'general-knowledge',summary:String(x.summary||`Ten sourced facts about ${c.subject}.`).slice(0,600),intro:String(x.intro||`An evidence-backed introduction to ${c.subject}, built from retrievable sources.`).slice(0,1800),reading_time:String(x.reading_time||'7 min read').slice(0,40),quality_score:quality,trigger:{source:'trend_pipeline',query:c.subject,signal_id:c.signal_id||null},generation:{workflow:'W10-R01 Evidence Research',execution:String($execution.id),source_count:evidence.length},items,related_topics:rel};}}
return [{json:{candidate_id:c.id,status:topic?'published':'retry',topic,error}}];
